using System;using System.IO;using System.Linq;using System.Data;using System.Drawing;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace MuEditorPhoenix {
 public partial class PhoenixEditorForm {internal bool RewardUiReady(){return Text=="Mu Editor Community Edition"&&invOption.Maximum==28&&invOption.Increment==4;}}
 public static class GrantTests {
  static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);}
  static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,message);}
  public static int Run(string report){string original=Guard.LocalData;string temp=Path.Combine(Path.GetTempPath(),"PhoenixGrant-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);Guard.LocalData=temp;
   try{for(int physical=0;physical<=28;physical+=4){var spec=new RewardSpec{ItemId=10488,Level=15,Durability=123,Additional=physical,Excellent=63,Skill=true,Luck=true};byte[] item=ItemCodec25.Create(spec,0x01020304);Check(ItemCodec25.Id(item)==10488,"extended category id");Check(ItemCodec25.Serial(item)==0x01020304,"big endian native serial");Check(4*((item[1]&3)+((item[7]&64)>>4))==physical,"additional physical encoding");Check(item.Skip(11).Take(8).All(b=>b==255)&&item.Skip(19).All(b=>b==0),"MuDevs25 empty advanced defaults");}
    foreach(int bad in new[]{-4,1,7,29,32})Reject(()=>ItemCodec25.AdditionalCode(bad),"invalid physical additional");
    byte[] muun=new byte[25];muun[0]=40;muun[9]=3;Check(ItemCodec25.Id(muun)==8232,"native category 16 plus period flag");
    string itemFile=Path.Combine(temp,"Item.xml");File.WriteAllText(itemFile,"<ItemList><Section Index='0'><Item Index='1' Name='Synthetic Sword' Width='2' Height='3' Durability='20' DW='1'/><Item Index='26' Name='Synthetic Socket' Width='1' Height='3' Durability='30'/></Section><Section Index='20'><Item Index='248' Name='Synthetic Modern Reward' Width='1' Height='1'/></Section></ItemList>");string socketDir=Path.Combine(temp,"Socket - Settings");Directory.CreateDirectory(socketDir);File.WriteAllText(Path.Combine(socketDir,"SocketItemType.xml"),"<SocketItemType><Item Section='0' Type='26'/></SocketItemType>");var catalog=new Catalog();catalog.Load(itemFile);Check(catalog.SocketItems.Contains(26),"socket metadata imported");
    var inv=new ItemBuffer(Enumerable.Repeat((byte)255,5975).ToArray());var ware=new ItemBuffer(Enumerable.Repeat((byte)255,6000).ToArray());var reward=new RewardSpec{ItemId=1,Level=15,Durability=60,Additional=28,Excellent=63,Skill=true,Luck=true,Copies=2};var slots=inv.AddRewards(reward,catalog,12,76);Check(slots.Count==2&&inv.NewItems.Count==2,"queued awards");Check(inv.NewItems.Values.Select(v=>v.RequestId).Distinct().Count()==2,"unique draft ids");Check(ItemCodec25.Serial(inv.Get(slots[0]))==0,"no serial consumed before save");
    string request=inv.NewItems[slots[0]].RequestId;ItemBuffer.Move(inv,slots[0],ware,0,catalog,0,120);Check(!inv.NewItems.ContainsKey(slots[0])&&ware.NewItems[0].RequestId==request&&inv.Empty(slots[0]),"new item tracking follows cross storage move");ware.Options(0,10,80,false,true,7,31);Check(ware.NewItems.ContainsKey(0)&&ItemCodec25.Serial(ware.Get(0))==0,"edit queued item preserves tracking");ware.CancelNew(0);Check(ware.Empty(0)&&ware.NewItems.Count==0&&!ware.Dirty,"cancel draft reward");
    var full=new ItemBuffer(Enumerable.Repeat((byte)255,5975).ToArray());byte[] before=(byte[])full.Data.Clone();reward.Copies=50;Reject(()=>full.AddRewards(reward,catalog,12,76),"no room rejects entire batch");Check(full.Data.SequenceEqual(before)&&full.NewItems.Count==0,"no partial queue on failed placement");
    var modern=new RewardSpec{ItemId=10488,Durability=1,Additional=28};var modernSlots=full.AddRewards(modern,catalog,12,76);Check(full.Id(modernSlots[0])==10488,"modern item placement");
    using(var form=new PhoenixEditorForm())Check(form.RewardUiReady(),"new name exact title and +28 UI");
    File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{status="PASS",tests=new[]{"MU Editor Phoenix branding and exact window title","additional +0..+28 roundtrip","reject invalid additional","5-bit item category and native serial encoding","25-byte defaults","socket metadata","queue and space checks","draft move/edit/cancel tracking","no serial before save","no partial placement"},productionWrites=false}));Console.WriteLine("PASS: grant codec, queue and UI");return 0;
   }finally{Guard.LocalData=original;}
  }
 }
}
